import Modal from "../../002 01-starting-project/01-starting-project/src/components/UI/Modal";
import "./Cart.css";
import React, { Fragment, useContext } from "react";
import CartContext from "../store/cart-context";
import ProductContext from "./store2/product-context";

const Cart = () => {
  const useCart = useContext(CartContext);
  const useProduct=useContext(ProductContext);

  const handleCart = () => {
    useCart.handleCart();
  };

  const closeCartHandling = () => {
    useCart.closeCart();
  };

  const addToCart = (size) => {
    const selectedItem = use.selectedItem;
    if (selectedItem) {
      const item = {
        id: selectedItem.id,
        name: `${selectedItem.name} (${size})`,
        price: selectedItem.price,
        size: size,
        quantity: 1, // Assuming quantity is always 1 when adding to cart
      };
      cartContext.addItems(item);
    }
  };
  return (
    <Fragment>
      <div className="cart">
        <label>items</label>
        <span>{useCart.totalQuantity}</span>
        <div className="button-div">
          <button className="cart-button" onClick={handleCart}>
            Open Cart
          </button>
        </div>
      </div>
      {useCart.openCart && (
        <Modal>
          <ul style={{border: "none"}}>
            {useCart.items.map((item) => (
              <li className="cartproduct" key={item.id}>
                <span>X{item.amount}</span>
                <span>{item.name}</span>

                <span>Rs {item.amount * item.price}</span>
              </li>
            ))}
          </ul>
          <div className="total">
            <span>Total Amount</span>
            <span>₹ {useCart.totalPrice}</span>
          </div>
          <div className="actions">
            <button className="button--alt" onClick={closeCartHandling}>
              Close
            </button>
            <button className="button">Order</button>
          </div>
        </Modal>
      )}
    </Fragment>
  );
};
export default Cart;
